// Regenerate parameters.default.txt from defaultParameters(), so the shipped
// defaults file can never drift (tests/configFile.test.ts round-trips it).
import { writeFileSync } from 'node:fs'
import { defaultParameters, serializeParametersTxt } from '../../src/generator'

const header = [
  '# Default parameters for the Hammerwatch Anniversary Edition Rogue-like Dungeon Generator.',
  '# Copy this file to the app\'s user-data folder as "parameters.txt" to override the',
  '# built-in defaults on startup, or import it from the GUI. key=value, one per line.',
  '#',
  '# Generated by scripts/dev/write-default-params.ts from defaultParameters() —',
  '# tests/configFile.test.ts asserts it round-trips, so it cannot drift.',
  '#',
  '# path is the Anniversary Edition install; themes are AE wall-set ids',
  '# (prison, armory, archives, chambers, prison2, crypt, mine_granite, ...).',
  '# Files written by the HW1 remake still import: their monster, theme and',
  '# music ids are translated (src/generator/catalog/substitutions.ts).'
]
const body = serializeParametersTxt(
  defaultParameters(),
  'C:/Program Files (x86)/Steam/steamapps/common/Hammerwatch Anniversary Edition',
  true
)
writeFileSync('parameters.default.txt', `${header.join('\n')}\n${body.replace(/\r\n/g, '\n')}`)
console.log('wrote parameters.default.txt')
